// Parse the LLM JSON, validate against the dashboard vocabulary, and build the PATCH body.
const SENTIMENTS = ['very_positive', 'positive', 'neutral', 'negative', 'very_negative'];
const URGENCIES = ['low', 'medium', 'high'];
const MODEL = 'claude-haiku-4-5';
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const source = $('One item per feedback row').itemMatching(i).json;
  let raw = item.json?.content?.[0]?.text ?? '';
  // Strip accidental code fences
  raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    // Leave the row unenriched; it will be retried next cycle. Surface the error.
    out.push({ json: { id: source.id, parseError: String(e), raw } });
    continue;
  }
  const clamp = (n) => Math.max(-1, Math.min(1, Number(n) || 0));
  out.push({
    json: {
      id: source.id,
      patch: {
        sentiment_label: SENTIMENTS.includes(parsed.sentiment_label) ? parsed.sentiment_label : 'neutral',
        sentiment_score: Number(clamp(parsed.sentiment_score).toFixed(2)),
        emotion: String(parsed.emotion ?? '').slice(0, 30) || null,
        urgency: URGENCIES.includes(parsed.urgency) ? parsed.urgency : 'low',
        summary: parsed.summary ?? null,
        explanation: parsed.explanation ?? null,
        key_phrases: Array.isArray(parsed.key_phrases) ? parsed.key_phrases.slice(0, 5).map(String) : [],
        recommended_response: parsed.recommended_response ?? null,
        enrichment_model: MODEL,
        enriched_at: new Date().toISOString(),
        enrichment_raw: parsed,
      },
    },
  });
}
return out;

// Parse failures land here — log them so a stuck row is visible in n8n executions.
console.log('Enrichment parse failures', JSON.stringify($input.all().map(i => i.json)));
return $input.all();
